using Microsoft.AspNetCore.Mvc;
namespace Bovis.Web.Controller;

/// <summary>
/// Debugging controller, shows simple message and current time. Useful for testing that the backend is running and responding to requests.
/// </summary>
[Route("bovis/hello")]
public class BovisHelloController : ControllerBase
{
    /// <summary>
    /// return a simple message and the current time.
    /// </summary>
    /// <returns></returns>
    [HttpGet]
    public IActionResult Get()
    {
        return Ok(new { Message = "Hello from Bovis", Time = DateTime.Now });
    }
}// -----------------------------------------------------------------------------
// DownloadController.cs
// -----------------------------------------------------------------------------
// This file defines a simple ASP.NET Core controller that provides a download
// endpoint. Depending on the query parameter, it returns either a static log
// file, a JSON representation of the current configuration archive, or a 404
// response if the requested item is unknown.
// -----------------------------------------------------------------------------
using Bovis.Interfaces.Configuration;
using Bovis.Services.Util;
using Microsoft.AspNetCore.Mvc;
using System.Text;
namespace Bovis.Web.Controller; 
/// <summary>
/// Handles HTTP GET requests to the "/download" route and returns downloadable
/// content based on the requested item.
/// </summary>
[Route("/download")]
public class DownloadController : Microsoft.AspNetCore.Mvc.Controller
{
    // Configuration store used to create configuration archives.
    // This dependency provides the ability to generate a configuration archive on demand.
    IConfigurationStore m_configurationStore;

    /// <summary>
    /// Constructs a new <see cref="DownloadController"/> with the required
    /// configuration store dependency.
    /// </summary>
    /// <param name="configurationStore">
    /// An implementation of <see cref="Bovis.Interfaces.Configuration.IConfigurationStore"/>
    /// used to create a configuration archive.
    /// </param>
    public DownloadController(IConfigurationStore configurationStore)
    {
        m_configurationStore = configurationStore;
    }

    /// <summary>
    /// Retrieves a file based on the supplied <paramref name="item"/> query
    /// parameter and returns it as a downloadable response.
    /// </summary>
    /// <param name="item">
    /// The name of the item to download. Supported values are "logs" and
    /// "config" (case‑insensitive). Any other value results in a 404 response.
    /// </param>
    /// <returns>
    /// An <see cref="IActionResult"/> containing the file bytes, appropriate
    /// content type, and suggested file name, or a 404 result if the item is
    /// not recognized.
    /// </returns>
    [HttpGet]
    public async Task<IActionResult> Get(string item)
    {
        byte[] fileBytes;
        string fileName;
        string contentType = "application/octet-stream";

        // Determine which file to serve based on the requested item.
        switch (item?.ToLower())
        {
            case "logs":
                // Return a simple text file containing placeholder log data.
                // Convert the placeholder string to UTF-8 encoded bytes.
                fileBytes = Encoding.UTF8.GetBytes("These are your logs...");
                fileName = "logs.txt";
                break;
            case "config":
                // Create a configuration archive, serialize it to JSON, and
                // return it as a downloadable JSON file.
                var archive = await m_configurationStore.CreateArchive();
                var json = ConversionUtility.AsJson(archive);
                // Convert the JSON string to UTF-8 encoded bytes.
                fileBytes = Encoding.UTF8.GetBytes(json);
                fileName = "bovis-config.json";
                contentType = "application/json";
                break;
            default:
                // If the item is not recognized, respond with 404.
                return NotFound("Item not found.");
        }

        // Return the file with the appropriate MIME type and filename.
        return File(fileBytes, contentType, fileName);
    }
}
